/**
 * HTTP details shared by the authorization-server host (`OAuthProvider`, `OAuthAuthorizationServer`)
 * and the resource-server host (`OAuthResourceServer`), so the two can't drift apart.
 */

import { version } from '../package.json';

/**
 * `User-Agent` sent on the library's own outbound fetches (EMA JWKS, Client ID Metadata Documents).
 * Workers' `fetch` sends none by default, and common WAF rule sets (AWS WAF's `NoUserAgent_HEADER`,
 * for one) block requests without it, so an IdP or client behind one would answer `403`. The RFC 9110
 * product token carries the release, and the comment points an operator at who is calling.
 */
export const OUTBOUND_USER_AGENT = `workers-oauth-provider/${version} (+https://github.com/cloudflare/workers-oauth-provider)`;

/**
 * Adds CORS headers for a browser client. The request's `Origin` is reflected: bearer tokens are
 * not ambient credentials, so any origin may present one it holds. Browser OAuth and MCP clients
 * need `WWW-Authenticate` (discovery, step-up) and `Retry-After` (backoff) exposed. Headers the
 * response already carries are kept, so an API handler can narrow who may read its responses.
 * Preflights (`OPTIONS`) are answered by the hosts before any handler runs and stay permissive, so
 * an MCP client's preflight always succeeds; the browser enforces the handler's policy on the actual
 * response, and sending the request carries no ambient credential to abuse.
 */
export function withCorsHeaders(response: Response, request: Request): Response {
  const origin = request.headers.get('Origin');
  if (!origin) return response;
  const cors = new Response(response.body, response);
  const setUnlessPresent = (name: string, value: string) => {
    if (!cors.headers.has(name)) cors.headers.set(name, value);
  };
  setUnlessPresent('Access-Control-Allow-Origin', origin);
  setUnlessPresent('Access-Control-Allow-Methods', '*');
  // Authorization must be named: `*` doesn't cover it.
  setUnlessPresent('Access-Control-Allow-Headers', 'Authorization, *');
  setUnlessPresent('Access-Control-Max-Age', '86400');
  appendHeaderValue(cors.headers, 'Vary', 'Origin');
  appendHeaderValue(cors.headers, 'Access-Control-Expose-Headers', 'WWW-Authenticate');
  appendHeaderValue(cors.headers, 'Access-Control-Expose-Headers', 'Retry-After');
  return cors;
}

/** Adds `value` to a comma-separated header unless it's already there (case-insensitively). */
function appendHeaderValue(headers: Headers, name: string, value: string): void {
  const values = (headers.get(name) ?? '')
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean);
  if (!values.some((item) => item.toLowerCase() === value.toLowerCase())) values.push(value);
  headers.set(name, values.join(', '));
}

/**
 * A resource's required scopes: `requiredScopes`, or the deprecated `resourceMetadata.scopes_supported`
 * it replaces. Both at once is ambiguous and refused.
 */
export function resolveRequiredScopes(
  requiredScopes: readonly string[] | undefined,
  deprecatedScopesSupported: readonly string[] | undefined
): string[] | undefined {
  if (requiredScopes !== undefined && deprecatedScopesSupported !== undefined) {
    throw new TypeError('Set requiredScopes only: resourceMetadata.scopes_supported is deprecated in its favour');
  }
  const scopes = requiredScopes ?? deprecatedScopesSupported;
  return scopes === undefined ? undefined : [...scopes];
}

/**
 * The scopes a protected resource advertises and challenges with: deduplicated, and without
 * `offline_access`, which is an authorization-server capability rather than a resource requirement.
 */
export function baselineResourceScopes(scopes: readonly string[]): string[] {
  return [...new Set(scopes)].filter((scope) => scope !== 'offline_access');
}

/**
 * The error your code throws to the library: from a `tokenExchangeCallback`, or from an
 * `OAuthResourceServer`'s `validateToken`, to answer with a standard OAuth error response instead
 * of a generic failure. Its own module so both hosts can use it without importing the package entry.
 */

/**
 * The internal reason behind an error response, forwarded to the `onError` hook and never
 * placed on the wire. `category` is a stable kebab-case subsystem (`client-authentication`,
 * `authorization-code-grant`, `refresh-token-grant`, `token-exchange-grant`,
 * `token-endpoint-request`, `token-revocation`, `token-issuance`, `resource-indicator`,
 * `client-registration`, `client-id-metadata-document`, `protected-resource`,
 * `enterprise-managed-authorization`, `token-exchange-callback`); `reason` is a stable
 * snake_case slug naming the exact check that failed. Treat both like enum members in semver.
 * `detail` may carry structured context such as a caught error; it is never a secret.
 */
export interface OAuthErrorInternal {
  /** Stable kebab-case subsystem that produced the error. */
  category: string;
  /** Stable snake_case slug naming the failed check, often more specific than the wire description. */
  reason: string;
  /** Optional structured context, e.g. the caught error or the offending parameter. */
  detail?: unknown;
}

/**
 * Options accepted by the {@link OAuthError} constructor.
 */
export interface OAuthErrorOptions {
  /**
   * Human-readable text returned in the `error_description` field.
   */
  description: string;

  /**
   * HTTP status code for the error response. Defaults to `400`.
   */
  statusCode?: number;

  /**
   * Additional response headers.
   *
   * For transient failures (e.g. upstream rate limits), set
   * `Retry-After` here so well-behaved clients back off instead of
   * retry-storming. Per RFC 7231 §7.1.3 the value may be either a
   * number of seconds or an HTTP-date.
   */
  headers?: Record<string, string>;

  /**
   * Internal reason forwarded to the `onError` hook and never sent on the wire. The library
   * sets it on every error it originates; a `tokenExchangeCallback` may set its own. An
   * `OAuthError` thrown without one reaches `onError` as
   * `{ category: 'token-exchange-callback', reason: 'callback_error', detail: error }`.
   */
  internal?: OAuthErrorInternal;
  /**
   * For `insufficient_scope` from an `OAuthResourceServer`'s `validateToken`: every scope the
   * operation needs, named in the `403` challenge. Defaults to the resource's `requiredScopes`.
   */
  requiredScopes?: string[];
}

/**
 * The OAuth error your code throws to the library, to answer with a standard OAuth error instead
 * of a generic failure. It is honoured in two places:
 *
 * - **`tokenExchangeCallback`** (token endpoint): the response is `{ error, error_description }`
 *   with `statusCode` (default `400`) and `headers`. `invalid_grant` also revokes the grant.
 *   Anything else thrown is a `500`.
 * - **`OAuthResourceServer`'s `validateToken`**: `invalid_token` is a `401` and
 *   `insufficient_scope` a `403`, each with a Bearer challenge (the latter naming
 *   `requiredScopes`); any other code keeps `statusCode` and `headers`, such as `429` with
 *   `Retry-After`. Anything else thrown is a `503`.
 *
 * Unexpected failures stay visible that way: the library doesn't catch everything and return 400.
 * (`OAuthProvider`'s `resolveExternalToken` uses `ExternalTokenError` instead.)
 *
 * @example
 * ```ts
 * import { OAuthError } from '@cloudflare/workers-oauth-provider';
 *
 * tokenExchangeCallback: async (options) => {
 *   if (options.grantType === 'refresh_token') {
 *     // refreshUpstream() may throw OAuthError from any depth
 *     return { newProps: await refreshUpstream(options.props) };
 *   }
 * }
 *
 * async function refreshUpstream(props) {
 *   const res = await fetch(...);
 *   if (res.status === 401) {
 *     // invalid_grant can never recover: the provider also revokes this grant and its tokens.
 *     throw new OAuthError('invalid_grant', { description: 'upstream refresh token is invalid' });
 *   }
 *   if (res.status === 429) {
 *     // Mirror upstream's Retry-After if present, otherwise pick a default.
 *     throw new OAuthError('temporarily_unavailable', {
 *       description: 'upstream rate limited',
 *       statusCode: 429,
 *       headers: { 'Retry-After': res.headers.get('retry-after') ?? '60' },
 *     });
 *   }
 *   return await res.json();
 * }
 * ```
 */
export class OAuthError extends Error {
  /** OAuth 2.0 error code. */
  public readonly code: string;
  /** Options controlling the OAuth error response. */
  public readonly options: OAuthErrorOptions & { statusCode: number };
  /** Human-readable description sent in the `error_description` field. */
  public readonly description: string;
  /** HTTP status code for the error response. */
  public readonly statusCode: number;
  /** Additional response headers. */
  public readonly headers?: Record<string, string>;
  /** Scopes an `insufficient_scope` challenge names. */
  public readonly requiredScopes?: string[];

  constructor(code: string, options: OAuthErrorOptions) {
    super(options.description);
    this.name = 'OAuthError';
    this.code = code;
    this.options = { ...options, statusCode: options.statusCode ?? 400 };
    this.description = this.options.description;
    this.statusCode = this.options.statusCode;
    this.headers = this.options.headers;
    this.requiredScopes = this.options.requiredScopes;
  }
}

/**
 * Consent and upstream-state primitives for authorization servers that sign users in through a
 * third-party OAuth provider (an MCP "proxy" server). They implement the protections the MCP
 * 2026-07-28 security best practices require under Confused Deputy → Mitigation:
 *
 * - consent per client before any redirect to the third party, with CSRF protection and anti-framing
 *   headers on the consent page;
 * - remembered consent, chosen per call, in a signed `__Host-` cookie bound to the client, its redirect
 *   URI and resource (and the user, when the caller knows them), reused only for a subset of the
 *   approved scopes;
 * - the approved scopes chosen on the consent page, from any the server supports;
 * - a random `state` stored server-side only after consent, bound to the browser by a `__Host-` cookie,
 *   single-use and short-lived.
 *
 * A transaction handle is 256 random bits. KV stores the record under the handle's SHA-256, encrypted
 * with a key derived from the handle, so KV alone reveals neither the request nor deployer data such as
 * a PKCE verifier. Each transaction has its own binding cookie, named after its hash and holding the
 * full hash, so several authorizations can be in flight in one browser (two tabs) without replacing each
 * other. Single use is `get` then `delete`, which KV cannot make atomic: two concurrent requests from the
 * same browser with the same handle could both pass; the cookie binding confines that to the browser
 * that started the transaction.
 */
import { AuthorizationError, authorizationErrorRedirect, isValidOAuthScopeToken } from './oauth-capabilities';
import type { AuthRequest, ClientInfo } from './oauth-provider';
import { isLoopbackHostname } from './oauth-resource';

/** Remember an approval so the consent page can be skipped for requests it already covers. */
export interface RememberConsentOptions {
  /** HMAC key for the approvals cookie: at least 32 characters, from a Worker secret. */
  secret: string;
  /** How long an approval is remembered. Defaults to 30 days. */
  maxAgeSeconds?: number;
  /**
   * The signed-in user, when you know them before consent (your own sign-in). The approval is then
   * bound to them as well, so another account on the same browser is asked again. Without it an
   * approval belongs to the browser, which suits a proxy server that only learns the user from the
   * third party after consent.
   */
  subject?: string;
}

/**
 * What a consent page must show, per the MCP authorization spec and security best practices.
 * Every string here may come from the client (dynamic registration or a CIMD document), so
 * escape all of it before rendering.
 */
export interface ConsentDescription {
  clientId: string;
  /** The client's name, or its client ID when it gave none. Self-asserted unless `clientDomain` is set. */
  clientName: string;
  /**
   * For a Client ID Metadata Document client: the hostname of its HTTPS client ID, a domain the
   * client controls. Show it prominently. Absent for registered clients, whose names are unverified.
   */
  clientDomain?: string;
  clientUri?: string;
  logoUri?: string;
  /** Where the tokens will be sent. */
  redirectUri: string;
  /**
   * The redirect URI's hostname, which the page MUST display. A native app's private-use URI
   * (`com.example.app:/callback`) has no host, so it's the whole URI instead.
   */
  redirectHost: string;
  /**
   * The redirect goes to a local app (`localhost`, `127.0.0.0/8`, `::1`). The page SHOULD warn:
   * any local process could be listening, whatever name the client claims.
   */
  redirectIsLoopback: boolean;
  /** The scopes being requested. */
  scope: string[];
}

/** A consent page to render: post `handle` back to {@link approveConsent}; send `headers` with the page. */
export interface ConsentTransaction {
  handle: string;
  headers: Headers;
}

/** The approved authorization request, with the cookies to set on the next response. */
export interface ApprovedConsent {
  request: AuthRequest;
  headers: Headers;
}

/** Where to send the browser after the user declined, with the cookies to set on that redirect. */
export interface DeniedConsent {
  request: AuthRequest;
  /** The client's redirect URI with `error=access_denied`, its `state`, and `iss` (RFC 9207). */
  redirectTo: string;
  headers: Headers;
}

/** The `state` to send to the third-party provider, with the binding cookie to set on the redirect. */
export interface UpstreamTransaction {
  state: string;
  headers: Headers;
}

/** The authorization request and data saved by `beginUpstream()`, recovered at the callback. */
export interface ResumedUpstream<Data = unknown> {
  request: AuthRequest;
  data: Data;
  headers: Headers;
}

const TRANSACTION_TTL_SECONDS = 600;
/** Default for the provider's `cookiePrefix` option. */
const DEFAULT_COOKIE_PREFIX = '__Host-oauth-';
const DEFAULT_REMEMBER_SECONDS = 30 * 24 * 60 * 60;
const MIN_SECRET_LENGTH = 32;
// Browsers cap a cookie near 4 KB; older approvals are dropped to stay under it.
const MAX_APPROVALS_COOKIE_BYTES = 3800;

type TransactionKind = 'consent' | 'upstream';
interface TransactionRecord {
  kind: TransactionKind;
  request: AuthRequest;
  data?: unknown;
}
/** A transaction whose binding and record checked out; `consume()` makes it single-use. */
interface OpenTransaction {
  record: TransactionRecord;
  cookieName: string;
  consume(): Promise<void>;
}
interface Approval {
  /** base64url SHA-256 of client ID, redirect URI and resource. */
  k: string;
  /** Approved scopes. */
  s: string[];
  /** Expiry, seconds since the epoch. */
  e: number;
}

/** Cookie names derived from the provider's `cookiePrefix`. */
export interface ConsentCookies {
  consent: string;
  upstream: string;
  approvals: string;
}

/** Throws a `TypeError` unless the prefix keeps the `__Host-` guarantees the MCP best practices require. */
export function consentCookies(prefix: string = DEFAULT_COOKIE_PREFIX): ConsentCookies {
  if (typeof prefix !== 'string' || !prefix.startsWith('__Host-') || !/^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/.test(prefix)) {
    throw new TypeError('cookiePrefix must start with "__Host-" and contain only cookie-name characters');
  }
  return { consent: `${prefix}consent`, upstream: `${prefix}upstream`, approvals: `${prefix}approvals` };
}

function validateRememberConsentOptions(options: RememberConsentOptions): void {
  if (typeof options !== 'object' || options === null) {
    throw new TypeError('remember must be an object with a secret');
  }
  if (typeof options.secret !== 'string' || options.secret.length < MIN_SECRET_LENGTH) {
    throw new TypeError(`remember.secret must be a string of at least ${MIN_SECRET_LENGTH} characters`);
  }
  const maxAge = options.maxAgeSeconds;
  if (maxAge !== undefined && (!Number.isInteger(maxAge) || maxAge <= 0)) {
    throw new TypeError('remember.maxAgeSeconds must be a positive integer');
  }
  if (options.subject !== undefined && (typeof options.subject !== 'string' || options.subject.length === 0)) {
    throw new TypeError('remember.subject must be a non-empty string');
  }
}

/** The facts a consent page must show for a request, given the client `lookupClient()` resolved. */
export function describeConsent(
  client: ClientInfo | null,
  request: AuthRequest,
  isClientIdMetadataDocument: boolean
): ConsentDescription {
  const redirectHost = new URL(request.redirectUri).hostname || request.redirectUri;
  return {
    clientId: request.clientId,
    // A blank registered name would leave the page with no visible client identity.
    clientName: client?.clientName?.trim() ? client.clientName : request.clientId,
    ...(isClientIdMetadataDocument ? { clientDomain: new URL(request.clientId).hostname } : {}),
    ...(client?.clientUri ? { clientUri: client.clientUri } : {}),
    ...(client?.logoUri ? { logoUri: client.logoUri } : {}),
    redirectUri: request.redirectUri,
    redirectHost,
    redirectIsLoopback: isLoopbackHostname(redirectHost),
    scope: [...request.scope],
  };
}

/** Start a consent transaction for an authorization request that must be shown to the user. */
export async function beginConsent(
  kv: KVNamespace,
  cookies: ConsentCookies,
  request: AuthRequest
): Promise<ConsentTransaction> {
  const { handle, hash } = await createTransaction(kv, { kind: 'consent', request });
  const headers = new Headers({
    'Set-Cookie': bindingCookie(transactionCookieName(cookies.consent, hash), hash, TRANSACTION_TTL_SECONDS),
    'Cache-Control': 'no-store',
    // Clickjacking protection for the consent page (MUST).
    'Content-Security-Policy': "frame-ancestors 'none'",
    'X-Frame-Options': 'DENY',
  });
  return { handle, headers };
}

/**
 * Consume a consent transaction the user approved. `scope`, when given, replaces the requested
 * scopes: the page may narrow them or offer more, but each must be one the server supports
 * (`supportedScopes`, from `scopesSupported`). `remember` stores the approval in a signed cookie.
 */
export async function approveConsent(
  kv: KVNamespace,
  cookies: ConsentCookies,
  supportedScopes: readonly string[] | undefined,
  request: Request,
  handle: string,
  options: { scope?: string[]; remember?: RememberConsentOptions } = {}
): Promise<ApprovedConsent> {
  if (options.remember !== undefined) validateRememberConsentOptions(options.remember);
  const transaction = await openTransaction(kv, request, cookies.consent, handle, 'consent');
  let approved = transaction.record.request;
  if (options.scope !== undefined) {
    // The checkboxes are the user's to edit, so every value is checked against what the server
    // supports; with no scopesSupported configured, any well-formed scope is the page's call.
    const supported = supportedScopes ? new Set(supportedScopes) : undefined;
    const valid = (scope: unknown) =>
      typeof scope === 'string' && isValidOAuthScopeToken(scope) && (!supported || supported.has(scope));
    if (!Array.isArray(options.scope) || !options.scope.every(valid)) {
      throw new AuthorizationError('invalid_scope', {
        description: 'Approved scopes must be ones this server supports',
      });
    }
    approved = { ...approved, scope: [...new Set(options.scope)] };
  }
  // Consumed only once the submission is valid, so a corrected resubmission of the same page works.
  await transaction.consume();
  const headers = new Headers({ 'Cache-Control': 'no-store' });
  headers.append('Set-Cookie', clearCookie(transaction.cookieName));
  if (options.remember) {
    headers.append('Set-Cookie', await rememberApproval(cookies, request, approved, options.remember));
  }
  return { request: approved, headers };
}

/**
 * Consume a consent transaction the user declined, and build the OAuth error redirect back to the
 * client: `error=access_denied`, the client's `state`, and `iss`. The redirect URI comes from the
 * stored request, which `parseAuthRequest()` validated, never from the form.
 */
export async function denyConsent(
  kv: KVNamespace,
  cookies: ConsentCookies,
  request: Request,
  handle: string,
  options: { description?: string } = {}
): Promise<DeniedConsent> {
  const transaction = await openTransaction(kv, request, cookies.consent, handle, 'consent');
  await transaction.consume();
  const record = transaction.record;
  const redirectTo = authorizationErrorRedirect(record.request, 'access_denied', options.description);
  const headers = new Headers({ 'Cache-Control': 'no-store', Location: redirectTo });
  headers.append('Set-Cookie', clearCookie(transaction.cookieName));
  return { request: record.request, redirectTo, headers };
}

/** Whether a remembered approval covers this request: same client, redirect URI and resource, subset of scopes. */
export async function isConsentRemembered(
  cookies: ConsentCookies,
  request: Request,
  authRequest: AuthRequest,
  remember: Pick<RememberConsentOptions, 'secret' | 'subject'>
): Promise<boolean> {
  validateRememberConsentOptions(remember);
  const approvals = await readApprovals(cookies, request, remember.secret);
  const key = await approvalKey(authRequest, remember.subject);
  const now = Math.floor(Date.now() / 1000);
  const approval = approvals.find((entry) => entry.k === key && entry.e > now);
  if (!approval) return false;
  const approvedScopes = new Set(approval.s);
  return authRequest.scope.every((scope) => approvedScopes.has(scope));
}

/**
 * Save an approved authorization request before redirecting to the third-party provider, and get
 * the `state` to send it. Call only after consent. Pass `headers` to add the binding cookie to
 * headers you are already sending, such as `approveConsent()`'s.
 */
export async function beginUpstream(
  kv: KVNamespace,
  cookies: ConsentCookies,
  request: AuthRequest,
  options: { data?: unknown; headers?: Headers } = {}
): Promise<UpstreamTransaction> {
  const { handle, hash } = await createTransaction(kv, { kind: 'upstream', request, data: options.data });
  const headers = options.headers ?? new Headers();
  headers.append(
    'Set-Cookie',
    bindingCookie(transactionCookieName(cookies.upstream, hash), hash, TRANSACTION_TTL_SECONDS)
  );
  headers.set('Cache-Control', 'no-store');
  return { state: handle, headers };
}

/** Recover the authorization request at the third-party provider's callback, from its `state` parameter. */
export async function finishUpstream<Data = unknown>(
  kv: KVNamespace,
  cookies: ConsentCookies,
  request: Request
): Promise<ResumedUpstream<Data>> {
  const state = new URL(request.url).searchParams.get('state');
  if (!state) {
    throw new AuthorizationError('invalid_request', { description: 'Missing state parameter' });
  }
  const transaction = await openTransaction(kv, request, cookies.upstream, state, 'upstream');
  await transaction.consume();
  const headers = new Headers({ 'Cache-Control': 'no-store' });
  headers.append('Set-Cookie', clearCookie(transaction.cookieName));
  return { request: transaction.record.request, data: transaction.record.data as Data, headers };
}

async function createTransaction(
  kv: KVNamespace,
  record: TransactionRecord
): Promise<{ handle: string; hash: string }> {
  const handle = base64url(crypto.getRandomValues(new Uint8Array(32)));
  const hash = await sha256Hex(handle);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const sealed = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv },
    await transactionKey(handle),
    new TextEncoder().encode(JSON.stringify(record))
  );
  await kv.put(`transaction:${hash}`, `${base64url(iv)}.${base64url(new Uint8Array(sealed))}`, {
    expirationTtl: TRANSACTION_TTL_SECONDS,
  });
  return { handle, hash };
}

async function openTransaction(
  kv: KVNamespace,
  request: Request,
  cookieBase: string,
  handle: string,
  kind: TransactionKind
): Promise<OpenTransaction> {
  if (typeof handle !== 'string' || handle.length === 0) {
    throw new AuthorizationError('invalid_request', { description: 'Missing transaction handle' });
  }
  const hash = await sha256Hex(handle);
  const cookieName = transactionCookieName(cookieBase, hash);
  const bound = readCookie(request, cookieName);
  if (!bound) {
    throw new AuthorizationError('invalid_request', {
      description: 'This authorization was not started in this browser; start again',
    });
  }
  if (!timingSafeEqual(hash, bound)) {
    throw new AuthorizationError('invalid_request', {
      description: 'This authorization belongs to a different browser session; start again',
    });
  }
  const key = `transaction:${hash}`;
  const expired = new AuthorizationError('invalid_request', {
    description: 'This authorization expired or was already used; start again',
  });
  const stored = await kv.get(key);
  if (!stored) throw expired;
  let record: TransactionRecord;
  try {
    const [iv, sealed] = stored.split('.');
    const plain = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: fromBase64url(iv) },
      await transactionKey(handle),
      fromBase64url(sealed)
    );
    record = JSON.parse(new TextDecoder().decode(plain));
  } catch {
    throw expired;
  }
  if (record.kind !== kind) throw expired;
  return { record, cookieName, consume: () => kv.delete(key) };
}

/** Only the holder of the handle can decrypt its record; KV keeps the hash, not the handle. */
async function transactionKey(handle: string): Promise<CryptoKey> {
  const material = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(`oauth-transaction-key:${handle}`));
  return crypto.subtle.importKey('raw', material, 'AES-GCM', false, ['encrypt', 'decrypt']);
}

/** One binding cookie per transaction, so concurrent authorizations in one browser don't collide. */
function transactionCookieName(base: string, hash: string): string {
  return `${base}-${hash.slice(0, 16)}`;
}

async function rememberApproval(
  cookies: ConsentCookies,
  request: Request,
  approved: AuthRequest,
  remember: RememberConsentOptions
): Promise<string> {
  const maxAge = remember.maxAgeSeconds ?? DEFAULT_REMEMBER_SECONDS;
  const now = Math.floor(Date.now() / 1000);
  const key = await approvalKey(approved, remember.subject);
  const approvals = (await readApprovals(cookies, request, remember.secret)).filter(
    (entry) => entry.e > now && entry.k !== key
  );
  approvals.push({ k: key, s: approved.scope, e: now + maxAge });
  let value = await signApprovals(approvals, remember.secret);
  while (value.length > MAX_APPROVALS_COOKIE_BYTES && approvals.length > 1) {
    approvals.shift();
    value = await signApprovals(approvals, remember.secret);
  }
  // The cookie lives as long as its longest-lived approval; each entry still expires on its own.
  const cookieMaxAge = Math.max(...approvals.map((entry) => entry.e)) - now;
  return `${cookies.approvals}=${value}; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=${cookieMaxAge}`;
}

async function readApprovals(cookies: ConsentCookies, request: Request, secret: string): Promise<Approval[]> {
  const value = readCookie(request, cookies.approvals);
  if (!value) return [];
  const [payload, signature] = value.split('.');
  if (!payload || !signature) return [];
  const key = await hmacKey(secret);
  let valid = false;
  try {
    valid = await crypto.subtle.verify('HMAC', key, fromBase64url(signature), new TextEncoder().encode(payload));
  } catch {
    return [];
  }
  if (!valid) return [];
  try {
    const parsed: unknown = JSON.parse(new TextDecoder().decode(fromBase64url(payload)));
    return Array.isArray(parsed) ? parsed.filter(isApproval) : [];
  } catch {
    return [];
  }
}

async function signApprovals(approvals: Approval[], secret: string): Promise<string> {
  const payload = base64url(new TextEncoder().encode(JSON.stringify(approvals)));
  const signature = await crypto.subtle.sign('HMAC', await hmacKey(secret), new TextEncoder().encode(payload));
  return `${payload}.${base64url(new Uint8Array(signature))}`;
}

function isApproval(value: unknown): value is Approval {
  if (!value || typeof value !== 'object') return false;
  const entry = value as Record<string, unknown>;
  return (
    typeof entry.k === 'string' &&
    typeof entry.e === 'number' &&
    Array.isArray(entry.s) &&
    entry.s.every((scope) => typeof scope === 'string')
  );
}

/** Approval is bound to the client, where its tokens go, which resource they are for, and the user if known. */
async function approvalKey(request: AuthRequest, subject: string | undefined): Promise<string> {
  const material = JSON.stringify([request.clientId, request.redirectUri, request.resource ?? null, subject ?? null]);
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(material));
  return base64url(new Uint8Array(digest));
}

function hmacKey(secret: string): Promise<CryptoKey> {
  return crypto.subtle.importKey('raw', new TextEncoder().encode(secret), { name: 'HMAC', hash: 'SHA-256' }, false, [
    'sign',
    'verify',
  ]);
}

function bindingCookie(name: string, value: string, maxAge: number): string {
  return `${name}=${value}; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=${maxAge}`;
}

function clearCookie(name: string): string {
  return `${name}=; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=0`;
}

function readCookie(request: Request, name: string): string | undefined {
  const header = request.headers.get('Cookie');
  if (!header) return undefined;
  for (const part of header.split(';')) {
    const separator = part.indexOf('=');
    if (separator === -1) continue;
    if (part.slice(0, separator).trim() === name) return part.slice(separator + 1).trim();
  }
  return undefined;
}

async function sha256Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(value));
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let difference = 0;
  for (let index = 0; index < a.length; index++) difference |= a.charCodeAt(index) ^ b.charCodeAt(index);
  return difference === 0;
}

function base64url(bytes: Uint8Array): string {
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromBase64url(value: string): Uint8Array {
  const base64 = value.replace(/-/g, '+').replace(/_/g, '/');
  const binary = atob(base64 + '='.repeat((4 - (base64.length % 4)) % 4));
  return Uint8Array.from(binary, (char) => char.charCodeAt(0));
}

/**
 * Loopback hosts where a plain `http` scheme is accepted for local development.
 * Matches RFC 8252 §7.3 loopback handling: 127.0.0.0/8, ::1, and `localhost`.
 */
export function isLoopbackHostname(hostname: string): boolean {
  const host = hostname.toLowerCase();
  if (host === 'localhost' || host === '::1' || host === '[::1]') return true;
  const ipv4 = /^127\.(\d{1,3})\.(\d{1,3})\.(\d{1,3})$/.exec(host);
  return ipv4 !== null && ipv4.slice(1).every((octet) => Number(octet) <= 255);
}

/**
 * Whether a canonical resource, issuer, or endpoint URL uses an accepted
 * scheme: `https`, or `http` on a loopback host so `wrangler dev` works on
 * http://localhost. Workers are always served over `https`, so there is no
 * deployment in which cleartext OAuth traffic to a remote host is correct,
 * and no option exists to allow it.
 */
export function hasAcceptedCanonicalScheme(url: URL): boolean {
  return url.protocol === 'https:' || (url.protocol === 'http:' && isLoopbackHostname(url.hostname));
}

/** Validate an RFC 3986-safe HTTP(S) resource identifier for RFC 8707. */
export function validateResourceUri(uri: string): boolean {
  if (!uri || typeof uri !== 'string') return false;

  // WHATWG URL repairs several invalid producer serializations. Reject those
  // before parsing so AS and RS components compare the same identifier bytes.
  if (
    !/^[\x21-\x7e]+$/.test(uri) ||
    /["\\#]/.test(uri) ||
    !/^[A-Za-z][A-Za-z0-9+.-]*:\/\/[^/?#]+(?:\/[^?#]*)?(?:\?[^#]*)?$/.test(uri) ||
    /%(?![0-9A-Fa-f]{2})/.test(uri) ||
    !/^[A-Za-z0-9:/?@!$&'()*+,;=._~%\[\]-]+$/.test(uri)
  ) {
    return false;
  }

  try {
    const parsed = new URL(uri);
    return parsed.protocol === 'http:' || parsed.protocol === 'https:';
  } catch {
    return false;
  }
}

/**
 * Whether a requested resource identifies a granted or configured resource.
 * Only ASCII case in the URI scheme and host is ignored, and an empty path is
 * equivalent to `/` (RFC 3986 §6.2.3), so a client that round-trips
 * `https://example.com` through a URL parser as `https://example.com/` still
 * names it. Port, path, query, a trailing slash after a path segment, user
 * information, and every other byte remain significant.
 */
export function resourceMatches(requested: string, granted: string): boolean {
  const foldedRequested = foldResourceSchemeAndHost(requested);
  const foldedGranted = foldResourceSchemeAndHost(granted);
  if (foldedRequested === undefined || foldedGranted === undefined) return false;
  return normalizeEmptyPath(foldedRequested) === normalizeEmptyPath(foldedGranted);
}

/**
 * Fold only the URI components whose comparison is ASCII case-insensitive: the
 * scheme and the host. A configured identifier is canonical when folding it is
 * the identity.
 */
export function foldResourceSchemeAndHost(resource: string): string | undefined {
  const schemeSeparator = resource.indexOf('://');
  if (schemeSeparator <= 0) return undefined;

  const authorityStart = schemeSeparator + 3;
  const authorityEndOffset = resource.slice(authorityStart).search(/[/?#]/);
  const authorityEnd = authorityEndOffset === -1 ? resource.length : authorityStart + authorityEndOffset;
  const authority = resource.slice(authorityStart, authorityEnd);
  const userInfoEnd = authority.lastIndexOf('@');
  const hostStart = userInfoEnd + 1;

  let hostEnd: number;
  if (authority[hostStart] === '[') {
    const closingBracket = authority.indexOf(']', hostStart + 1);
    if (closingBracket === -1) return undefined;
    hostEnd = closingBracket + 1;
  } else {
    const portSeparator = authority.indexOf(':', hostStart);
    hostEnd = portSeparator === -1 ? authority.length : portSeparator;
  }

  const asciiLower = (value: string) => value.replace(/[A-Z]/g, (character) => character.toLowerCase());
  return (
    asciiLower(resource.slice(0, schemeSeparator)) +
    '://' +
    authority.slice(0, hostStart) +
    asciiLower(authority.slice(hostStart, hostEnd)) +
    authority.slice(hostEnd) +
    resource.slice(authorityEnd)
  );
}

/** RFC 3986 §6.2.3: for http and https an empty path is equivalent to "/". */
function normalizeEmptyPath(resource: string): string {
  const authorityStart = resource.indexOf('://') + 3;
  const pathOffset = resource.slice(authorityStart).search(/[/?#]/);
  if (pathOffset === -1) return `${resource}/`;
  const pathStart = authorityStart + pathOffset;
  return resource[pathStart] === '/' ? resource : `${resource.slice(0, pathStart)}/${resource.slice(pathStart)}`;
}

/**
 * Whether a request carries every query parameter of a canonical resource. A
 * query-bearing resource identifier names a more specific resource: a request
 * may add parameters of its own but must preserve the resource's.
 */
export function requestCarriesResourceQuery(requestUrl: URL, resourceUrl: URL): boolean {
  for (const [name, value] of resourceUrl.searchParams) {
    if (!requestUrl.searchParams.getAll(name).includes(value)) return false;
  }
  return true;
}

/**
 * The configured resource a client-supplied resource indicator names when it is
 * not an exact match: one with the same origin and path whose query parameters
 * the indicator carries, as a request URL the resource covers would. With
 * several such resources, the one with the most query parameters wins and a tie
 * names none. A value without a query never matches here.
 */
export function findCoveringResource(requested: string, configured: readonly string[]): string | undefined {
  let url: URL;
  try {
    url = new URL(requested);
  } catch {
    return undefined;
  }
  if (url.search === '') return undefined;
  const covering = configured
    .map((resource) => ({ resource, url: new URL(resource) }))
    .filter(
      (candidate) =>
        candidate.url.origin === url.origin &&
        (candidate.url.pathname || '/') === (url.pathname || '/') &&
        requestCarriesResourceQuery(url, candidate.url)
    )
    .map(({ resource, url }) => ({ resource, specificity: [...url.searchParams].length }))
    .sort((a, b) => b.specificity - a.specificity);
  if (covering.length === 0) return undefined;
  if (covering.length > 1 && covering[0].specificity === covering[1].specificity) return undefined;
  return covering[0].resource;
}

const OAUTH_SCOPE_TOKEN_PATTERN = /^[\x21\x23-\x5B\x5D-\x7E]+$/;

export type AuthorizationErrorCode =
  | 'invalid_request'
  | 'invalid_target'
  | 'unauthorized_client'
  | 'access_denied'
  | 'unsupported_response_type'
  | 'invalid_scope'
  | 'server_error'
  | 'temporarily_unavailable';

export interface AuthorizationErrorOptions {
  /** Wire-safe OAuth authorization error description. */
  description: string;
  /** Exact registered redirect URI. Present only after client and redirect validation. */
  redirectUri?: string;
  /** Original client state, when supplied. */
  state?: string;
  /** Authorization server issuer for RFC 9207 error responses. */
  issuer?: string;
}

/**
 * The OAuth error redirect back to a client (RFC 6749 §4.1.2.1): `error`, an optional
 * `error_description`, the client's `state`, and `iss` (RFC 9207). Pass only a request the
 * library validated, from `parseAuthRequest()`, `finishUpstream()` or `approveConsent()`,
 * never one rebuilt from user input.
 *
 * ```ts
 * if (new URL(req.url).searchParams.get('error')) {
 *   return Response.redirect(authorizationErrorRedirect(original, 'access_denied'), 302);
 * }
 * ```
 */
export function authorizationErrorRedirect(
  request: { redirectUri: string; state?: string; issuer?: string },
  code: AuthorizationErrorCode,
  description?: string
): string {
  const redirect = new URL(request.redirectUri);
  // A registered redirect URI may carry its own query; never let a stale value stand in for ours.
  for (const key of ERROR_RESPONSE_PARAMETERS) redirect.searchParams.delete(key);
  redirect.searchParams.set('error', code);
  if (description) redirect.searchParams.set('error_description', description);
  if (request.state) redirect.searchParams.set('state', request.state);
  if (request.issuer) redirect.searchParams.set('iss', request.issuer);
  return redirect.href;
}

const ERROR_RESPONSE_PARAMETERS = ['error', 'error_description', 'error_uri', 'state', 'iss'];

/**
 * Expected authorization-request validation failure. Absence of `redirectUri`
 * means a caller MUST render locally and MUST NOT redirect.
 */
export class AuthorizationError extends Error {
  public readonly code: AuthorizationErrorCode;
  public readonly description: string;
  public readonly redirectUri?: string;
  public readonly state?: string;
  public readonly issuer?: string;
  /**
   * The ready-made error redirect back to the client, set only when a redirect is safe
   * (`redirectUri` was validated). Without it, render the error locally.
   */
  public readonly redirectTo?: string;

  constructor(code: AuthorizationErrorCode, options: AuthorizationErrorOptions) {
    super(options.description);
    this.name = 'AuthorizationError';
    this.code = code;
    this.description = options.description;
    this.redirectUri = options.redirectUri;
    this.state = options.state;
    this.issuer = options.issuer;
    this.redirectTo = options.redirectUri ? safeErrorRedirect(code, options) : undefined;
  }
}

/** The error redirect, or undefined when the registered URI can't be parsed: render locally then. */
function safeErrorRedirect(code: AuthorizationErrorCode, options: AuthorizationErrorOptions): string | undefined {
  try {
    return authorizationErrorRedirect(
      {
        redirectUri: options.redirectUri!,
        state: options.state,
        issuer: options.issuer,
      },
      code,
      options.description
    );
  } catch {
    return undefined;
  }
}

/** @internal Attach context after exact client redirect validation succeeds. */
export function withAuthorizationRedirect(
  error: AuthorizationError,
  redirectUri: string,
  state: string | undefined,
  issuer: string
): AuthorizationError {
  return new AuthorizationError(error.code, {
    description: error.description,
    redirectUri,
    state,
    issuer,
  });
}

/** PKCE transformation methods implemented by the authorization server. */
type PkceCodeChallengeMethod = 'plain' | 'S256';

export interface OAuthServerCapabilities {
  readonly grantTypes: readonly string[];
  readonly responseTypes: readonly string[];
  readonly tokenEndpointAuthMethods: readonly string[];
  readonly codeChallengeMethods: readonly PkceCodeChallengeMethod[];
  /** Accept RFC 8252 private-use URI scheme redirects (native apps), beyond https and loopback http. */
  readonly allowPrivateUseRedirectUris: boolean;
}

interface ClientCapabilities {
  readonly grantTypes: readonly string[];
  readonly responseTypes: readonly string[];
  readonly tokenEndpointAuthMethod: string;
}

/** Client-advertised capabilities parsed from OAuth client metadata. */
interface ClientMetadataCapabilities {
  readonly grantTypes: readonly string[];
  readonly responseTypes: readonly string[];
  readonly tokenEndpointAuthMethod?: string;
  readonly tokenEndpointAuthMethodsSupported?: readonly string[];
}

export function buildOAuthServerCapabilities(options: {
  allowTokenExchangeGrant: boolean;
  enterpriseManagedAuthorization: boolean;
  allowPrivateUseRedirectUris: boolean;
}): OAuthServerCapabilities {
  return {
    grantTypes: [
      'authorization_code',
      'refresh_token',
      ...(options.allowTokenExchangeGrant ? ['urn:ietf:params:oauth:grant-type:token-exchange'] : []),
      ...(options.enterpriseManagedAuthorization ? ['urn:ietf:params:oauth:grant-type:jwt-bearer'] : []),
    ],
    responseTypes: ['code'],
    tokenEndpointAuthMethods: ['client_secret_basic', 'client_secret_post', 'none'],
    codeChallengeMethods: ['S256'],
    allowPrivateUseRedirectUris: options.allowPrivateUseRedirectUris,
  };
}

export function validateClientCapabilities(server: OAuthServerCapabilities, client: ClientCapabilities): void {
  if (!server.tokenEndpointAuthMethods.includes(client.tokenEndpointAuthMethod)) {
    throw new Error(`Unsupported token_endpoint_auth_method: ${client.tokenEndpointAuthMethod}`);
  }

  const unsupportedGrant = client.grantTypes.find((grantType) => !server.grantTypes.includes(grantType));
  if (unsupportedGrant) throw new Error(`Unsupported grant_type: ${unsupportedGrant}`);

  const unsupportedResponse = client.responseTypes.find((responseType) => !server.responseTypes.includes(responseType));
  if (unsupportedResponse) throw new Error(`Unsupported response_type: ${unsupportedResponse}`);

  if (client.grantTypes.includes('authorization_code') !== client.responseTypes.includes('code')) {
    throw new Error('grant_types authorization_code and response_types code must be registered together');
  }
}

const SHARED_SECRET_TOKEN_ENDPOINT_AUTH_METHODS = new Set([
  'client_secret_basic',
  'client_secret_post',
  'client_secret_jwt',
]);

function negotiateTokenEndpointAuthMethod(options: {
  acceptedMethods: readonly string[];
  defaultMethod: string;
  preferredMethod: string | undefined;
  supportedMethods: readonly string[] | undefined;
  context: string;
}): string {
  const { acceptedMethods, defaultMethod, preferredMethod, supportedMethods, context } = options;
  if (preferredMethod !== undefined && supportedMethods !== undefined && !supportedMethods.includes(preferredMethod)) {
    throw new Error('token_endpoint_auth_method must be included in token_endpoint_auth_methods_supported');
  }

  const advertisedMethods = supportedMethods ?? [preferredMethod ?? defaultMethod];
  const effectiveMethod =
    preferredMethod !== undefined && acceptedMethods.includes(preferredMethod)
      ? preferredMethod
      : acceptedMethods.find((method) => advertisedMethods.includes(method));

  if (effectiveMethod !== undefined) return effectiveMethod;

  const advertised = [...new Set([...(preferredMethod === undefined ? [] : [preferredMethod]), ...advertisedMethods])];
  throw new Error(
    `${context} does not support an accepted token endpoint authentication method. ` +
      `Supported methods: ${acceptedMethods.join(', ')}. ` +
      `Client advertised: ${advertised.length > 0 ? advertised.join(', ') : '(none)'}`
  );
}

/** Asymmetric method a CIMD client may use when its document supplies usable keys. */
const PRIVATE_KEY_JWT = 'private_key_jwt';

/**
 * Every token endpoint authentication method a CIMD client may use with this server, in the
 * server's order of preference.
 *
 * A metadata document has no registration response, so the client learns nothing about which
 * method this server picked. It chooses one per request from this server's metadata. So every
 * method both sides support stays usable: a document that offers `none` and `private_key_jwt`
 * (ChatGPT's does) works with either, and a document that offers only `private_key_jwt` must
 * use it.
 */
function negotiateCimdTokenEndpointAuthMethods(
  server: OAuthServerCapabilities,
  preferredMethod: string | undefined,
  supportedMethods: readonly string[] | undefined,
  privateKeyJwt: boolean
): string[] {
  if (preferredMethod !== undefined && SHARED_SECRET_TOKEN_ENDPOINT_AUTH_METHODS.has(preferredMethod)) {
    throw new Error(`CIMD clients cannot use symmetric token endpoint authentication method: ${preferredMethod}`);
  }
  if (preferredMethod !== undefined && supportedMethods !== undefined && !supportedMethods.includes(preferredMethod)) {
    throw new Error('token_endpoint_auth_method must be included in token_endpoint_auth_methods_supported');
  }

  const acceptedMethods = [
    ...server.tokenEndpointAuthMethods.filter((method) => !SHARED_SECRET_TOKEN_ENDPOINT_AUTH_METHODS.has(method)),
    ...(privateKeyJwt ? [PRIVATE_KEY_JWT] : []),
  ];
  const advertisedMethods = supportedMethods ?? [preferredMethod ?? 'none'];
  const methods = acceptedMethods.filter((method) => advertisedMethods.includes(method));
  if (methods.length > 0) return methods;

  const advertised = [...new Set([...(preferredMethod === undefined ? [] : [preferredMethod]), ...advertisedMethods])];
  throw new Error(
    'CIMD client does not support an accepted token endpoint authentication method. ' +
      `Supported methods: ${acceptedMethods.join(', ')}. ` +
      `Client advertised: ${advertised.length > 0 ? advertised.join(', ') : '(none)'}`
  );
}

/**
 * Negotiates choice-valued authentication metadata while keeping DCR grant and
 * response registration strict.
 */
export function negotiateDynamicClientRegistrationCapabilities(
  server: OAuthServerCapabilities,
  client: ClientMetadataCapabilities
): { grantTypes: string[]; responseTypes: string[]; tokenEndpointAuthMethod: string } {
  const effective = {
    grantTypes: [...client.grantTypes],
    responseTypes: [...client.responseTypes],
    tokenEndpointAuthMethod: negotiateTokenEndpointAuthMethod({
      acceptedMethods: server.tokenEndpointAuthMethods,
      defaultMethod: 'client_secret_basic',
      preferredMethod: client.tokenEndpointAuthMethod,
      supportedMethods: client.tokenEndpointAuthMethodsSupported,
      context: 'Client',
    }),
  };

  validateClientCapabilities(server, effective);
  return effective;
}

/**
 * Selects the capabilities from a Client ID Metadata Document that this
 * authorization server supports. CIMD documents may advertise extension
 * capabilities alongside the flow used with this server, so unsupported grant
 * and response types are omitted from the effective client metadata instead of
 * invalidating an otherwise usable client.
 *
 * The effective subset is still checked for grant/response consistency, and
 * token endpoint authentication must have a mutually supported method.
 */
export function negotiateCimdClientCapabilities(
  server: OAuthServerCapabilities,
  client: ClientMetadataCapabilities,
  options: {
    /** Whether the document supplies keys and an algorithm this server can verify `private_key_jwt` with. */
    readonly privateKeyJwt: boolean;
  } = { privateKeyJwt: false }
): {
  grantTypes: string[];
  responseTypes: string[];
  tokenEndpointAuthMethod: string;
  tokenEndpointAuthMethods: string[];
} {
  const tokenEndpointAuthMethods = negotiateCimdTokenEndpointAuthMethods(
    server,
    client.tokenEndpointAuthMethod,
    client.tokenEndpointAuthMethodsSupported,
    options.privateKeyJwt
  );
  const effective = {
    grantTypes: client.grantTypes.filter((grantType) => server.grantTypes.includes(grantType)),
    responseTypes: client.responseTypes.filter((responseType) => server.responseTypes.includes(responseType)),
    // The weakest usable method is the client's recorded method, so a client that may present
    // `none` is held to the public-client rules (PKCE) on every request.
    tokenEndpointAuthMethod: tokenEndpointAuthMethods[0],
    tokenEndpointAuthMethods,
  };

  validateClientCapabilities(
    { ...server, tokenEndpointAuthMethods: [...server.tokenEndpointAuthMethods, PRIVATE_KEY_JWT] },
    effective
  );
  return effective;
}

export function validateAuthorizationResponseType(
  server: OAuthServerCapabilities,
  responseType: string,
  clientResponseTypes: readonly string[] | undefined
): void {
  if (!responseType) {
    throw new AuthorizationError('invalid_request', { description: 'response_type is required' });
  }
  if (!server.responseTypes.includes(responseType)) {
    throw new AuthorizationError('unsupported_response_type', {
      description: `The authorization server does not support response_type ${responseType}`,
    });
  }
  if (!(clientResponseTypes ?? ['code']).includes(responseType)) {
    throw new AuthorizationError('unauthorized_client', {
      description: `The client is not registered for response_type ${responseType}`,
    });
  }
}

/** Parse a PKCE method, applying RFC 7636's default of `plain`. */
export function normalizePkceCodeChallengeMethod(method: string | undefined): PkceCodeChallengeMethod {
  const effectiveMethod = method ?? 'plain';
  if (effectiveMethod !== 'plain' && effectiveMethod !== 'S256') {
    throw new AuthorizationError('invalid_request', {
      description: `Unsupported PKCE code_challenge_method: ${effectiveMethod}`,
    });
  }
  return effectiveMethod;
}

/** Require a syntactically valid PKCE method that the server advertises. */
export function validatePkceCodeChallengeMethod(
  server: OAuthServerCapabilities,
  method: string | undefined
): PkceCodeChallengeMethod {
  const effectiveMethod = normalizePkceCodeChallengeMethod(method);
  if (!server.codeChallengeMethods.includes(effectiveMethod)) {
    throw new AuthorizationError('invalid_request', {
      description: 'The plain PKCE method is not allowed. Use S256 instead.',
    });
  }
  return effectiveMethod;
}

/** Validate authorization-request PKCE against server and client capabilities. */
export function validateAuthorizationPkce(
  server: OAuthServerCapabilities,
  request: {
    readonly responseType: string;
    readonly codeChallenge?: string;
    readonly codeChallengeMethod?: string;
  },
  client: Pick<ClientCapabilities, 'tokenEndpointAuthMethod'>
): void {
  if (request.codeChallenge) {
    validatePkceCodeChallengeMethod(server, request.codeChallengeMethod);
    return;
  }
  if (request.codeChallengeMethod) {
    throw new AuthorizationError('invalid_request', {
      description: 'PKCE code_challenge is required when code_challenge_method is provided.',
    });
  }
  if (request.responseType === 'code' && client.tokenEndpointAuthMethod === 'none') {
    throw new AuthorizationError('invalid_request', {
      description: 'Public clients must use PKCE with the authorization code flow.',
    });
  }
}

export function validateAuthorizationServerScopes(scopes: readonly string[] | undefined): void {
  if (!scopes) return;
  if (scopes.some((scope) => !isValidOAuthScopeToken(scope))) {
    throw new TypeError('scopesSupported must contain valid OAuth scope tokens');
  }
  if (new Set(scopes).size !== scopes.length) {
    throw new TypeError('scopesSupported must not contain duplicate values');
  }
}

export function isValidOAuthScopeToken(scopeToken: string): boolean {
  return OAUTH_SCOPE_TOKEN_PATTERN.test(scopeToken);
}

import { WorkerEntrypoint } from 'cloudflare:workers';
import {
  hasAcceptedCanonicalScheme,
  requestCarriesResourceQuery,
  resourceMatches,
  validateResourceUri,
} from './oauth-resource';
import { isValidOAuthScopeToken } from './oauth-capabilities';
import { OAuthError } from './oauth-error';
import { baselineResourceScopes, resolveRequiredScopes, withCorsHeaders } from './oauth-http';

const PROTECTED_RESOURCE_WELL_KNOWN_PREFIX = '/.well-known/oauth-protected-resource';
const NO_CACHE_HEADERS = { 'Cache-Control': 'no-store', Pragma: 'no-cache' } as const;

/** RFC 9728 metadata published by a standalone OAuth resource server. */
export interface OAuthResourceMetadata {
  /** The one canonical HTTPS identifier for this protected resource. */
  resource: string;
  /** Authorization server issuers that can issue tokens for this resource. */
  authorization_servers: string[];
  /**
   * Minimal scopes used to access the protected resource.
   * @deprecated Use `requiredScopes`, which this becomes on the wire. Setting both is refused.
   */
  scopes_supported?: string[];
  /** Bearer-token presentation methods. This implementation supports only `header`. */
  bearer_methods_supported?: string[];
  /** Human-readable protected-resource name. */
  resource_name?: string;
}

/** Successful result returned by the application's token validator. */
export interface OAuthResourceTokenValidation<Props> {
  /** Application data exposed to the protected handler as `ctx.props`. */
  props: Props;
  /** Canonical audience to which the token is bound. */
  audience: string;
  /** Optional absolute expiry as seconds since the Unix epoch. */
  expiresAt?: number;
  /**
   * Scopes the token carries. `OAuthAuthorizationServer.validateToken()` always reports them;
   * a handler needs them to answer with {@link insufficientScope}.
   */
  scope?: string[];
  /** Subject the token was issued for. */
  userId?: string;
  /** Client the token was issued to. */
  clientId?: string;
}

/**
 * What the host verified about the bearer token before calling the handler, exposed as
 * `ctx.auth` beside the application's `ctx.props`. Both hosts set it: `OAuthResourceServer`
 * from the validator's result, `OAuthProvider` from its own token record.
 */
export interface OAuthResourceAuth {
  /** The token as presented. It is already in the request's `Authorization` header; never log it. */
  token: string;
  /** Canonical resource the token was accepted for. */
  audience: string;
  /** Absolute expiry as seconds since the Unix epoch, when known. */
  expiresAt?: number;
  /** Scopes the token carries; empty when the validator reported none. */
  scope: string[];
  /** Subject the token was issued for, when known. */
  userId?: string;
  /** Client the token was issued to, when known. */
  clientId?: string;
}

/** The execution context a protected handler receives: `props` from the validator, `auth` from the host. */
export type OAuthResourceContext<Props> = ExecutionContext<Props> & { readonly auth: OAuthResourceAuth };

/**
 * Validates a bearer token presented to one resource. `null` for a token that is not
 * valid for that resource; a thrown error fails closed as `503`.
 */
export type OAuthResourceTokenValidator<Props> = (
  resource: string,
  token: string
) => Promise<OAuthResourceTokenValidation<Props> | null>;

/**
 * Protected application handler called after successful token validation: an object with
 * `fetch`, or a `WorkerEntrypoint` subclass instantiated per request with `(ctx, env)`. Either
 * way `ctx.props` carries what the validator returned and `ctx.auth` what the host verified.
 */
export type OAuthResourceHandler<Env, Props> =
  | { fetch(request: Request, env: Env, ctx: OAuthResourceContext<Props>): Response | Promise<Response> }
  | (new (ctx: OAuthResourceContext<Props>, env: Env) => { fetch(request: Request): Response | Promise<Response> });

/** Configuration for {@link OAuthResourceServer}. */
export interface OAuthResourceServerOptions<Env = Cloudflare.Env, Props = unknown> {
  /** RFC 9728 metadata, including this server's one canonical resource. */
  resourceMetadata: OAuthResourceMetadata;
  /**
   * The scopes required for accessing this resource (MCP: the minimal set for basic use). Published
   * as its protected resource metadata's `scopes_supported` and named in the `401` challenge, so
   * clients request them first; not the authorization server's catalogue, `scopesSupported`.
   * Operations that need more ask for it with `insufficientScope()` (step-up). `offline_access` is
   * removed automatically. Leave unset when your consent page picks the scopes.
   *
   * Advertised, not enforced: the handler decides whether a token is sufficient (`ctx.auth.scope`),
   * because only it knows the deployment's scope hierarchy (a broader scope implying a narrower
   * one), which MCP requires servers to honour.
   */
  requiredScopes?: string[];

  /** Application handler for the canonical resource URL and its path descendants. */
  handler: OAuthResourceHandler<Env, Props>;
  /**
   * The validator for a request. The host calls what you return with this server's
   * canonical resource and the bearer token, so neither is repeated here.
   *
   * - The authorization server in another Worker, over a Service Binding to a
   *   `WorkerEntrypoint` that exposes `OAuthAuthorizationServer.validateToken()`:
   *   `(env) => env.AUTH_SERVER.validateToken`
   * - The authorization server in this Worker:
   *   `(env) => (resource, token) => authorizationServer.validateToken(resource, token, env)`
   * - Anything else, at your own risk: a function that validates the token for `resource`,
   *   such as one that recognises an upstream API's credentials and validates them itself
   *   before falling back to the authorization server.
   *
   * Return `null` for a token that isn't valid here (a `401` challenge). Throw an `OAuthError`
   * for a specific answer: `temporarily_unavailable` with `statusCode: 429` and a `Retry-After`
   * header, `insufficient_scope` with `requiredScopes`, or `invalid_token` with a description.
   * Anything else thrown is a validator failure (`503`). An `OAuthError` thrown in another
   * Worker arrives over RPC as a plain `Error`, so throw it in this Worker's validator.
   */
  validateToken(env: Env, request: Request): OAuthResourceTokenValidator<Props>;
}

type MutableExecutionContext<Props> = Omit<ExecutionContext<Props>, 'props'> & {
  props: Props;
  auth: OAuthResourceAuth;
};

/**
 * The response for a valid token that lacks the scopes an operation needs (RFC 6750 §3.1,
 * MCP scope challenge handling): `403` with `WWW-Authenticate: Bearer error="insufficient_scope"`,
 * the `scope` the operation requires and the `resource_metadata` URL the client already knows.
 * Name every scope the operation needs in one response; clients treat the list as complete.
 *
 * ```ts
 * if (!ctx.auth.scope.includes('calendar:write')) return insufficientScope(ctx.auth, ['calendar:write']);
 * ```
 */
export function insufficientScope(auth: OAuthResourceAuth, scope: string[], description?: string): Response {
  if (
    !Array.isArray(scope) ||
    scope.length === 0 ||
    scope.some((value) => typeof value !== 'string' || !isValidOAuthScopeToken(value))
  ) {
    throw new TypeError('insufficientScope requires at least one valid OAuth scope token');
  }
  let challenge = `Bearer realm="OAuth", error="insufficient_scope", scope="${[...new Set(scope)].join(' ')}"`;
  challenge += `, resource_metadata="${getResourceMetadataUrl(auth.audience)}"`;
  if (description !== undefined) {
    // The header copy must be a valid quoted-string (RFC 7230 §3.2.6) and a valid header value:
    // visible ASCII and spaces only, without quotes or backslashes. The JSON body keeps the original.
    const quotable = description
      .replace(/["\\]/g, '')
      .replace(/[^\x21-\x7e]+/g, ' ')
      .trim();
    if (quotable) challenge += `, error_description="${quotable}"`;
  }
  return new Response(
    JSON.stringify({
      error: 'insufficient_scope',
      ...(description !== undefined ? { error_description: description } : {}),
    }),
    {
      status: 403,
      headers: { ...NO_CACHE_HEADERS, 'Content-Type': 'application/json', 'WWW-Authenticate': challenge },
    }
  );
}

/**
 * One OAuth protected resource, in the authorization server's Worker or its own. Publishes
 * RFC 9728 metadata, challenges unauthenticated requests, validates the bearer token through
 * the configured `validateToken`, enforces audience and expiry on what it returns, and routes
 * only the canonical resource and its descendants to the application handler.
 *
 * `export default new OAuthResourceServer({ … })`, or dispatch to `fetch()` from your own
 * router, exactly as with `OAuthAuthorizationServer`.
 */
export class OAuthResourceServer<Env = Cloudflare.Env, Props = unknown> {
  readonly #options: OAuthResourceServerOptions<Env, Props>;
  readonly #validated: ValidatedResourceConfiguration;

  constructor(options: OAuthResourceServerOptions<Env, Props>) {
    this.#validated = validateOptions(options);
    this.#options = options;
  }

  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const options = this.#options;
    const validated = this.#validated;
    const url = new URL(request.url);

    if (isProtectedResourceMetadataPath(url)) {
      if (request.method === 'OPTIONS') {
        return withCorsHeaders(
          new Response(null, {
            status: 204,
            headers: { 'Content-Length': '0' },
          }),
          request
        );
      }

      // RFC 9728 §3 fixes the origin and path; a cache-busting query must not hide the
      // document, while a resource's own query parameters must still be present.
      if (!isMetadataUrlRequest(url, validated.metadataUrl)) {
        return withCorsHeaders(new Response(null, { status: 404 }), request);
      }

      if (request.method !== 'GET' && request.method !== 'HEAD') {
        return withCorsHeaders(
          new Response(null, {
            status: 405,
            headers: { Allow: 'GET, HEAD, OPTIONS' },
          }),
          request
        );
      }

      const metadata = Response.json(validated.metadata, { headers: NO_CACHE_HEADERS });
      return withCorsHeaders(
        request.method === 'HEAD' ? new Response(null, { status: 200, headers: metadata.headers }) : metadata,
        request
      );
    }

    if (!isCanonicalResourceRequest(url, validated.resourceUrl)) {
      return new Response(null, { status: 404 });
    }

    if (request.method === 'OPTIONS') {
      return withCorsHeaders(
        new Response(null, {
          status: 204,
          headers: { 'Content-Length': '0' },
        }),
        request
      );
    }

    const token = [REDACTED]'Authorization'));
    if (!token) {
      return withCorsHeaders(createBearerChallenge(url, validated, false), request);
    }

    let validation: OAuthResourceTokenValidation<Props> | null;
    try {
      validation = await options.validateToken(env, request)(validated.resource, token);
    } catch (error) {
      // An OAuthError is the validator's answer (429 with Retry-After, 403 insufficient_scope, ...);
      // anything else is the validator failing.
      if (error instanceof OAuthError) return withCorsHeaders(createOAuthErrorResponse(error, url, validated), request);
      return withCorsHeaders(createValidationUnavailableResponse(), request);
    }

    if (!isValidTokenValidation(validation, validated.resource)) {
      return withCorsHeaders(createBearerChallenge(url, validated, true), request);
    }

    const context = ctx as MutableExecutionContext<Props>;
    context.props = validation.props;
    context.auth = {
      token,
      audience: validated.resource,
      ...(validation.expiresAt !== undefined ? { expiresAt: validation.expiresAt } : {}),
      scope: [...(validation.scope ?? [])],
      ...(validation.userId !== undefined ? { userId: validation.userId } : {}),
      ...(validation.clientId !== undefined ? { clientId: validation.clientId } : {}),
    };
    const handler = options.handler;
    const response = isEntrypointClass(handler)
      ? await new handler(context, env).fetch(request)
      : await handler.fetch(request, env, context);
    return withCorsHeaders(response, request);
  }
}

interface ValidatedResourceConfiguration {
  resource: string;
  resourceUrl: URL;
  metadataUrl: URL;
  metadata: OAuthResourceMetadata;
}

function validateOptions<Env, Props>(options: OAuthResourceServerOptions<Env, Props>): ValidatedResourceConfiguration {
  if (!options || typeof options !== 'object') {
    throw new TypeError('OAuth resource server options are required');
  }
  if (
    !options.handler ||
    (!isEntrypointClass(options.handler) && typeof (options.handler as { fetch?: unknown }).fetch !== 'function')
  ) {
    throw new TypeError('handler must provide a fetch function or extend WorkerEntrypoint');
  }
  if (typeof options.validateToken !== 'function') {
    throw new TypeError('validateToken must be a function');
  }

  const resource = options.resourceMetadata?.resource;
  const resourceUrl = parseCanonicalUrl(resource);
  if (!resourceUrl) {
    throw new TypeError(
      'resourceMetadata.resource must be a canonical absolute HTTPS URI without a fragment (http is accepted only on a loopback host)'
    );
  }
  // The metadata namespace is dispatched to discovery before the protected handler, so a
  // resource inside it could never receive a request.
  if (isProtectedResourceMetadataPath(resourceUrl)) {
    throw new TypeError(
      `resourceMetadata.resource must not be inside the ${PROTECTED_RESOURCE_WELL_KNOWN_PREFIX} namespace`
    );
  }

  const authorizationServers = options.resourceMetadata.authorization_servers;
  if (!Array.isArray(authorizationServers) || authorizationServers.length === 0) {
    throw new TypeError('resourceMetadata.authorization_servers must contain at least one issuer');
  }
  for (const issuer of authorizationServers) {
    const issuerUrl = parseCanonicalUrl(issuer);
    if (!issuerUrl || issuerUrl.search || issuerUrl.hash) {
      throw new TypeError(
        'resourceMetadata.authorization_servers must contain canonical HTTPS issuer URLs (http is accepted only on a loopback host)'
      );
    }
  }

  const bearerMethods = options.resourceMetadata.bearer_methods_supported;
  if (bearerMethods !== undefined && (bearerMethods.length !== 1 || bearerMethods[0] !== 'header')) {
    throw new TypeError("resourceMetadata.bearer_methods_supported only supports 'header'");
  }

  const configuredScopes =
    resolveRequiredScopes(options.requiredScopes, options.resourceMetadata.scopes_supported) ?? [];
  if (configuredScopes.some((scope) => typeof scope !== 'string' || !isValidOAuthScopeToken(scope))) {
    throw new TypeError(
      'requiredScopes (or the deprecated resourceMetadata.scopes_supported) must contain valid OAuth scope tokens'
    );
  }
  const resourceScopes = baselineResourceScopes(configuredScopes);

  return {
    resource,
    resourceUrl,
    metadataUrl: new URL(getResourceMetadataUrl(resource)),
    metadata: {
      resource,
      authorization_servers: [...authorizationServers],
      ...(resourceScopes.length ? { scopes_supported: resourceScopes } : {}),
      bearer_methods_supported: bearerMethods ? [...bearerMethods] : ['header'],
      ...(options.resourceMetadata.resource_name !== undefined
        ? { resource_name: options.resourceMetadata.resource_name }
        : {}),
    },
  };
}

function parseCanonicalUrl(value: unknown): URL | null {
  if (typeof value !== 'string' || !validateResourceUri(value)) {
    return null;
  }

  let parsed: URL;
  try {
    parsed = new URL(value);
  } catch {
    return null;
  }

  if (
    !hasAcceptedCanonicalScheme(parsed) ||
    parsed.username ||
    parsed.password ||
    parsed.protocol !== parsed.protocol.toLowerCase() ||
    parsed.hostname !== parsed.hostname.toLowerCase()
  ) {
    return null;
  }

  // `URL` repairs default ports, dot segments, backslashes, and a missing root
  // slash. A bare origin is the only alternate spelling allowed by RFC 9728.
  if (parsed.href !== value && parsed.origin !== value) {
    return null;
  }

  return parsed;
}

function getResourceMetadataUrl(resource: string): string {
  const parsed = new URL(resource);
  const suffix = parsed.pathname === '/' ? '' : parsed.pathname;
  return `${parsed.origin}${PROTECTED_RESOURCE_WELL_KNOWN_PREFIX}${suffix}${parsed.search}`;
}

/** The same test the combined provider applies to its handlers. */
function isEntrypointClass<Env, Props>(
  handler: OAuthResourceHandler<Env, Props>
): handler is new (
  ctx: OAuthResourceContext<Props>,
  env: Env
) => { fetch(request: Request): Response | Promise<Response> } {
  return typeof handler === 'function' && handler.prototype instanceof WorkerEntrypoint;
}

function isProtectedResourceMetadataPath(url: URL): boolean {
  return (
    url.pathname === PROTECTED_RESOURCE_WELL_KNOWN_PREFIX ||
    url.pathname.startsWith(`${PROTECTED_RESOURCE_WELL_KNOWN_PREFIX}/`)
  );
}

function isMetadataUrlRequest(requestUrl: URL, metadataUrl: URL): boolean {
  return (
    requestUrl.origin === metadataUrl.origin &&
    requestUrl.pathname === metadataUrl.pathname &&
    requestCarriesResourceQuery(requestUrl, metadataUrl)
  );
}

function isCanonicalResourceRequest(requestUrl: URL, resourceUrl: URL): boolean {
  if (requestUrl.origin !== resourceUrl.origin) return false;
  if (!requestCarriesResourceQuery(requestUrl, resourceUrl)) return false;

  const resourcePath = resourceUrl.pathname;
  if (requestUrl.pathname === resourcePath) return true;
  if (resourcePath === '/') return requestUrl.pathname.startsWith('/');

  const descendantPrefix = resourcePath.endsWith('/') ? resourcePath : `${resourcePath}/`;
  return requestUrl.pathname.startsWith(descendantPrefix);
}

function parseBearerToken(authorization: string | null): string | null {
  if (!authorization) return null;
  const match = /^Bearer[\t ]+([^\s,]+)$/i.exec(authorization);
  return match?.[1] || null;
}

function isValidTokenValidation<Props>(
  validation: OAuthResourceTokenValidation<Props> | null,
  canonicalResource: string
): validation is OAuthResourceTokenValidation<Props> {
  if (!validation || typeof validation !== 'object') return false;
  if (typeof validation.audience !== 'string' || !resourceMatches(validation.audience, canonicalResource)) return false;
  if (!Object.prototype.hasOwnProperty.call(validation, 'props')) return false;

  if (validation.expiresAt !== undefined) {
    if (typeof validation.expiresAt !== 'number' || !Number.isFinite(validation.expiresAt)) return false;
    if (validation.expiresAt <= Date.now() / 1000) return false;
  }
  if (validation.scope !== undefined) {
    if (!Array.isArray(validation.scope)) return false;
    if (validation.scope.some((scope) => typeof scope !== 'string' || !isValidOAuthScopeToken(scope))) return false;
  }
  if (validation.userId !== undefined && typeof validation.userId !== 'string') return false;
  if (validation.clientId !== undefined && typeof validation.clientId !== 'string') return false;

  return true;
}

function createBearerChallenge(
  requestUrl: URL,
  validated: ValidatedResourceConfiguration,
  invalidToken: boolean
): Response {
  let challenge = 'Bearer realm="OAuth"';
  // RFC 9728 §5.1: every request this resource covers, including path-boundary
  // descendants of the canonical path, points at the one canonical document.
  if (isCanonicalResourceRequest(requestUrl, validated.resourceUrl)) {
    challenge += `, resource_metadata="${validated.metadataUrl.href}"`;
  }
  if (invalidToken) {
    challenge += ', error="invalid_token"';
  }
  // MCP: the initial challenge names the scopes to request, so a client can ask for them up front.
  const scopes = validated.metadata.scopes_supported;
  if (scopes && scopes.length > 0) {
    challenge += `, scope="${scopes.join(' ')}"`;
  }

  return new Response(null, {
    status: 401,
    headers: {
      ...NO_CACHE_HEADERS,
      'WWW-Authenticate': challenge,
    },
  });
}

/**
 * A validator's `OAuthError` as the response. RFC 6750 fixes `invalid_token` at `401` and
 * `insufficient_scope` at `403`, each with a Bearer challenge (unless the error brings its own);
 * any other code keeps the error's status and headers, such as a `429` with `Retry-After`.
 */
function createOAuthErrorResponse(
  error: OAuthError,
  requestUrl: URL,
  validated: ValidatedResourceConfiguration
): Response {
  const headers: Record<string, string> = { ...NO_CACHE_HEADERS, 'Content-Type': 'application/json', ...error.headers };
  const hasChallenge = Object.keys(headers).some((name) => name.toLowerCase() === 'www-authenticate');
  let status = error.statusCode;
  if (error.code === 'invalid_token') {
    status = 401;
    if (!hasChallenge)
      headers['WWW-Authenticate'] = createBearerChallenge(requestUrl, validated, true).headers.get('WWW-Authenticate')!;
  } else if (error.code === 'insufficient_scope') {
    status = 403;
    if (!hasChallenge) {
      const scopes = [...new Set(error.requiredScopes ?? validated.metadata.scopes_supported ?? [])];
      // A malformed answer from the validator is the validator failing, like any other bad throw.
      if (scopes.some((scope) => typeof scope !== 'string' || !isValidOAuthScopeToken(scope))) {
        return createValidationUnavailableResponse();
      }
      headers['WWW-Authenticate'] =
        'Bearer realm="OAuth", error="insufficient_scope"' +
        (scopes.length > 0 ? `, scope="${scopes.join(' ')}"` : '') +
        `, resource_metadata="${validated.metadataUrl.href}"`;
    }
  }
  return new Response(JSON.stringify({ error: error.code, error_description: error.description }), { status, headers });
}

function createValidationUnavailableResponse(): Response {
  return new Response(null, {
    status: 503,
    headers: NO_CACHE_HEADERS,
  });
}
